import React, { useState, useEffect } from 'react';
import { useHistory } from 'react-router-dom';
import initializeData from '../utils/InitializeData';
import LocalStorageImporter from './LocalStorageImporter';
import NavItems from '../site/NavItems';
import AppAppearanceDialog from './AppAppearanceDialog';

const Admin = () => {

    const history = useHistory();
    const demoActiveKey = 'reactorAdminDemoActive';
    const demoTimerKey = '__reactorAdminDemoTimer';
    const demoDelayMs = 10000;

    const [key, setKey] = useState('');
    const [action, setAction] = useState('view');
    const [data, setData] = useState(null);
    const [message, setMessage] = useState(null);
    const [editableData, setEditableData] = useState('');
    const [isDemoRunning, setIsDemoRunning] = useState(false);
    const [showDataInterface, setShowDataInterface] = useState(false);

    const localDataItems = [
        'Select a key',
        'tideChart',
        'wind',
        'isWind',
        'isTide',
        'isSwell1',
        'isSwell2',
        'swell1Direction',
        'swell2Direction',
        'tideNow',
        'tide',
        'tideDirection',
        'heightTime',
        'swellData',
        'swellCollapse',
        'windSpeed',
        'height',
        'sunset',
        'sunrise',
        'logId',
        'locations',
        'postDirectory',
        'tides',
        'spots',
        'spot',
        'tideData',
        'waterTemp',
        'airTemp',
        'edit',
        'elapsedTime',
        'stopwatchStartTime',
        'stopwatchPause',
        'distance',
        'latitude',
        'longitude',
        'TripFuelTracker',
        'usdPerGallon',
        'gallons',
        'location',
        'odometer',
        'trainingElapsedTime',
        'trainingActiveIndex',
        'trainingStartTime',
        'activeTimers',
        'goalData',
        'trainingData',
        'waveTracking',
        'projects',
        'recipeTracking',
        'noteTracking',
        'journalTracking',
        'journalSort',
        'eventTracking',
        'tracking',
        'chargeTracking',
        'taskTracking',
        'linkTracking',
        'vueTodosRevert',
        'vueTodosSaved',
        'aisles',
        'vueTodos',
        'tax',
        'longitude',
        'latitude',
        'pausedTodos',
        'localTimedItems',
        'todos',
        'standardWinner',
        'ping pongWinner',
        'golfWinner',
        'cornholeWinner',
        'dartsWinner',
        'horseWinner',
        'horseshoesWinner',
        'bocciWinner',
        'dominosWinner',
        'surfWinner',
        'heatLog',
        'winner',
        'surfWinner',
        'game',
        'gameStatus',
        'golfPars',
        'players',
        'timerTimeRemaining',
        'timerStartTime',
        'timerPause',
        'time',
        'timeLeft',
        'notes',
        'expenses',
        'exchangeRates',
        'circuitTracking',
        'circuitSort',
        'activeCircuitTime',
        'activeIndex',
        'activated',
        'countdown',
        'ticker',
        'breathing',
        'All Data'
    ];
    
    const defaultData = [
        {
            'skill': 'Surfing',
            'time': '00:00:00',
            'percentage': '0'
        }
    ];

    useEffect(() => {
        console.log(`editableData: ${editableData}`);
    }, [editableData]);

    useEffect(() => {
        console.log(`data: ${data}`);
    }, [data]);

    const clearDemoTimer = () => {
        if (window[demoTimerKey]) {
            window.clearTimeout(window[demoTimerKey]);
            window[demoTimerKey] = null;
        }
    };

    const stopDemo = () => {
        localStorage.removeItem(demoActiveKey);
        clearDemoTimer();
        setIsDemoRunning(false);
    };

    const startDemo = () => {
        const demoRoutes = NavItems.filter((item) => item && item !== 'Admin');
        if (!demoRoutes.length) {
            setMessage('No demo routes found.');
            return;
        }

        stopDemo();
        localStorage.setItem(demoActiveKey, 'true');
        setIsDemoRunning(true);
        setMessage(`▶️ Demo started (${demoRoutes.length} routes, ${demoDelayMs / 1000}s each).`);

        let demoIndex = 0;

        const runDemoStep = () => {
            if (localStorage.getItem(demoActiveKey) !== 'true') {
                stopDemo();
                return;
            }

            if (demoIndex >= demoRoutes.length) {
                stopDemo();
                return;
            }

            const routeLabel = demoRoutes[demoIndex];
            demoIndex += 1;
            history.push(`/${routeLabel}`);

            if (demoIndex < demoRoutes.length) {
                window[demoTimerKey] = window.setTimeout(runDemoStep, demoDelayMs);
            } else {
                stopDemo();
            }
        };

        runDemoStep();
    };

    const handleView = () => {
        const storedData = initializeData(key, null);
        if (key === '*' || key.toLowerCase() === 'all data') {
              const allData = Object.fromEntries(Object.entries(localStorage));
              setMessage(null);
              setData(JSON.stringify(allData, null, 2));
              return;
        }
        const startsWithBracket = (str) => String(str).charAt(0) === '[' || String(str).charAt(0) === '{';
        if (storedData) {
            const displayData = (startsWithBracket(storedData))
            ? JSON.stringify(storedData, null, 2)
            : storedData;
            //const formattedData = storedData
            /*const formattedData = displayData
                .replace(/,/g, ',\n')
                .replace(/}/g, '\n}')
                .replace(/{/g, '\n{\n')
                .replace(/]/g, ']\n')
                .replace(/\[/g, '[\n');
            */
            //setData(formattedData);
            setMessage(null);
            setData(displayData);
        } else {
            setMessage(`No data found for ${key}.`);
        }
    };
    const handleNew = () => {
        const storedData = initializeData(key, null);
        if (storedData) {
            setMessage(`Data already exists for ${key}.`);
        } else {
            const displayData = JSON.stringify(defaultData, null, 2);
            setMessage(null);
            setData(displayData);
        }
    };

    const handleRemove = () => {
        localStorage.removeItem(key);
        setMessage(`Data for key '${key}' has been removed.`);
        setData(null);
        setEditableData('');
    };
    
    const handleRemoveMenuSystem = () => {
        localStorage.removeItem('menus');
        localStorage.removeItem('NavItemsMeta');
        localStorage.removeItem('menuItems');
        setMessage(`Data for menus, NavItemsMeta, and menuItems has been removed.`);
        setData(null);
        setEditableData('');
    };

    const handleEdit = () => {
        localStorage.setItem(key, data);
        setData(null);
        setEditableData('');
        setMessage(`Changes have been saved to ${key}`);
    };
    const handleAdd = () => {
        localStorage.setItem(key, data);
        setData(null);
        setEditableData('');
        setMessage(`${key} has been added to localStorage`);
    };
    const handleActionChange = (e) => {
        stopDemo();
        setAction(e.target.value);
        setData(null);
        setMessage(null);
        setEditableData('');
    };
    const handleKeyChange = (e) => {
        setKey(e.target.value);
        setData(null);
        setMessage(null);
        setEditableData('');
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        if (key.trim() === '') {
            alert('Please enter a localStorage key.');
            return;
        }
        if (action === 'view') {
            handleView();
        } else if (action === 'remove') {
            handleRemove();
        } else if (action === 'edit') {
            handleView(); // Load data for editing
        } else if (action === 'add') {
            handleNew();
        }
    };
    return (
        <div className='mt--30'>
            <form className='containerDetail' onSubmit={handleSubmit}>
                <div className='containerDetail bg-lite contentLeft p-20 size20 color-yellow mb-5'>
                    Admin Tool
                </div>
                <AppAppearanceDialog 
                    open={true}
                    onClose={() => console.log('AppAppearanceDialog closed')}
                    onApply={() => console.log('AppAppearanceDialog apply')}
                />
                <div
                    className='containerDetail button color-lite contentLeft mt-5 bg-blue p-20 size20'
                    aria-expanded={showDataInterface}
                    aria-controls='data-interface-section'
                    onClick={() => setShowDataInterface((prev) => !prev)}
                >
                    {showDataInterface ? '▼' : '►'} Data Interface
                </div>
                {showDataInterface && (
                    <div id='data-interface-section' className='containerDetail contentLeft bg-lite p-10 mt-5'>
                        <div>
                            <div className='containerDetail p-20 bold color-lite size20 bg-lite'>
                                LocalStorage
                            </div>
                            <label>
                                <select
                                    className='containerDetail width-100-percent width--5 color-lite p-20 size20 mb-5'
                                    value={key}
                                    onChange={handleKeyChange}
                                >
                                    {
                                        localDataItems.map((itemKey, index) => (
                                            <option key={`${itemKey}-${index}`} value={itemKey}>{itemKey}</option>
                                        ))
                                    }
                                </select>
                                <div className='flexContainer mt-5'>
                                    <div className='containerDetail flex9Column contentRight bg-lite color-lite p-20 size20'>
                                        Key:
                                    </div>
                                    <input
                                        id='key'
                                        name='key'
                                        className='containerDetail flex2Column color-lite p-20 size20 ml-5'
                                        type='text'
                                        value={key}
                                        onChange={(e) => setKey(e.target.value)}
                                    />
                                </div>
                            </label>
                        </div>
                        <label className='flexContainer mt-10'>
                            <div className='containerDetail flex9Column contentRight bg-lite color-lite p-20 size20 mt--5'>
                                Action:
                            </div>
                            <select
                                className='containerDetail flex2Column color-lite p-20 size20 mt--5'
                                value={action}
                                onChange={handleActionChange}
                            >
                                <option value='view'>View</option>
                                <option value='edit'>Edit</option>
                                <option value='add'>Add</option>
                                <option value='remove'>Remove</option>
                            </select>
                        </label>
                        <div 
                            className='containerDetail button width-100-percent bg-green contentLeft color-lite p-20 size20 mt-5' 
                            type='submit'
                        >
                            Select
                        </div>
                    </div>
                )}
                {/* Always visible controls */}
                <div 
                    className='containerDetail button bg-red color-lite contentLeft p-20 size20 mt-5 mb-5' 
                    onClick={handleRemoveMenuSystem}
                >
                    🗑️ Remove Menu System Data
                </div>
                {isDemoRunning
                    ? <div
                        className='containerDetail button width-100-percent bg-red color-lite contentLeft p-20 size20'
                        type='button'
                        onClick={() => { stopDemo(); setMessage('⏹️ Demo stopped.'); }}
                    >
                        ⏹️ Stop Demo
                    </div>
                    : <div
                        className='containerDetail button bg-green color-lite contentLeft p-20 size20'
                        onClick={startDemo}
                    >
                        ▶️ Demo
                    </div>
                }
            </form>

            {/* Data display and edit/add UI, only show if Data Interface is open */}
            {showDataInterface && action === 'view' && data && (
                <div className='containerDetail width-100-percent'>
                    <h3>View Data</h3>
                    <pre className='containerDetail width-100-percent contentLeft'>
                        {data}
                    </pre>
                </div>
            )}

            {showDataInterface && action === 'edit' && data && (
                <div className='containerDetail width-100-percent'>
                    <h3>Edit Data</h3>
                    <textarea
                        className='containerDetail width-100-percent' 
                        rows='10'
                        cols='50'
                        value={data}
                        onChange={(e) => setData(e.target.value)}
                    />
                    <br />
                    <div className='containerDetail button width-100-percent bg-green' onClick={handleEdit}>Save Changes</div>
                </div>
            )}
            {showDataInterface && action === 'add' && data && (
                <div className='containerDetail width-100-percent' >
                    <h3>Add Data</h3>
                    <textarea
                        className='containerDetail width-100-percent' 
                        rows='10'
                        cols='50'
                        value={data}
                        onChange={(e) => setData(e.target.value)}
                    />
                    <br />
                    <div className='containerDetail button width-100-percent bg-green'  onClick={handleAdd}>Add Data</div>
                </div>
            )}
            {message && (
                <div className='containerDetail width-100-percent color-neogreen'>
                    <h3>{message}</h3>
                </div>
            )}
            <LocalStorageImporter />
        </div>
    );
};

export default Admin;